CREATE TABLE IF NOT EXISTS `kalimdor_stats_talent` (
  `spell` int(10) unsigned NOT NULL,
  `class` tinyint(3) unsigned NOT NULL,
  `tree` varchar(32) NOT NULL,
  `points` tinyint(3) unsigned NOT NULL COMMENT 'the talent points this rank stands for',
  PRIMARY KEY (`spell`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='kalimdor: talent ranks and their trees (stats exporter)';
DELETE FROM `kalimdor_stats_talent`;

CREATE TABLE IF NOT EXISTS `kalimdor_stats_recipe` (
  `spell` int(10) unsigned NOT NULL,
  `skill` smallint(5) unsigned NOT NULL,
  PRIMARY KEY (`spell`, `skill`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='kalimdor: spells a profession teaches (stats exporter)';
DELETE FROM `kalimdor_stats_recipe`;

CREATE TABLE IF NOT EXISTS `kalimdor_stats_profession` (
  `skill` smallint(5) unsigned NOT NULL,
  `name` varchar(32) NOT NULL,
  PRIMARY KEY (`skill`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='kalimdor: professions, gathering ones too (stats exporter)';
DELETE FROM `kalimdor_stats_profession`;

CREATE TABLE IF NOT EXISTS `kalimdor_stats_specialty` (
  `spell` int(10) unsigned NOT NULL,
  `skill` smallint(5) unsigned NOT NULL,
  `name` varchar(32) NOT NULL,
  PRIMARY KEY (`spell`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='kalimdor: profession specializations (stats exporter)';
DELETE FROM `kalimdor_stats_specialty`;

